"""QA: is engine B's standard basis of Sigma a weight basis of a torus generated by rotations in real planes?"""
import os, sys, itertools
import sympy as sp
ROOT = '/Users/libotao/Desktop/N4_Costello_BV_2026-10-27'
sys.path.insert(0, os.path.join(ROOT, 'step2/composite_qsk/composite/engine_b/src.nosync/vendor'))
import realization as RZ
R, Rb = RZ.R, RZ.Rb
def rot(a, b):   # rho(e_a) rho(e_b) on Sigma
    return sp.simplify(Rb[a] * R[b])
diag = {}
for a, b in itertools.combinations(range(10), 2):
    M = rot(a, b)
    off = any(M[i, j] != 0 for i in range(16) for j in range(16) if i != j)
    if not off:
        diag[(a, b)] = [M[i, i] for i in range(16)]
print('planes whose rotation is diagonal on Sigma (standard basis):')
for k, v in diag.items():
    print(k, v)
